1	package clusterdata.query;
2	
3	import clusterdata.datatypes.JobEvent;
4	import clusterdata.datatypes.TaskEvent;
5	import clusterdata.utils.AppBase;
6	import clusterdata.utils.CsvSource;
7	import org.apache.flink.api.common.functions.RichMapFunction;
8	import org.apache.flink.api.java.tuple.Tuple2;
9	import org.apache.flink.api.java.utils.ParameterTool;
10	import org.apache.flink.configuration.Configuration;
11	import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
12	import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
13	
14	import java.io.BufferedWriter;
15	import java.io.FileWriter;
16	import java.io.IOException;
17	import java.util.HashMap;
18	import java.util.Map;
19	
20	public class LongestSessionPerJob extends AppBase {
21	
22	    public static void main(String[] args) throws Exception {
23	
24	        ParameterTool params = ParameterTool.fromArgs(args);
25	        String taskInput = params.get("task_input", null);
26	        String jobInput = params.get("job_input", null);
27	        String outputPath = params.get("output", null);
28	        System.out.println("task_input  " + taskInput);
29	        System.out.println("job_input  " + jobInput);
30	        final long sesssize = params.getLong("sesssize", 600) * 1_000_000; // convert to microseconds
31	
32	        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
33	        env.setParallelism(1);
34	
35	        env.addSource(taskSourceOrTest(CsvSource.createTaskEventSource(taskInput)))
36	                .filter(event -> event.eventType == 0) // SUBMIT events only
37	                .map(new RichMapFunction<TaskEvent, Tuple2<Long, Long>>() {
38	                    @Override
39	                    public Tuple2<Long, Long> map(TaskEvent event) {
40	                        return Tuple2.of(event.jobId, event.timestamp);
41	                    }
42	                })
43	                .addSink(new StageProcessorSink(sesssize, outputPath));
44	
45	        env.execute("LongestSessionPerJob");
46	    }
47	
48	    public static class StageProcessorSink extends RichSinkFunction<Tuple2<Long, Long>> {
49	        private final long sessionGap;
50	        private final String outputPath;
51	        private Map<Long, JobStageState> jobStates;
52	        private BufferedWriter writer;
53	
54	        public StageProcessorSink(long sessionGap, String outputPath) {
55	            this.sessionGap = sessionGap;
56	            this.outputPath = outputPath;
57	        }
58	
59	        @Override
60	        public void open(Configuration parameters) throws Exception {
61	            jobStates = new HashMap<>();
62	            writer = new BufferedWriter(new FileWriter(outputPath, false));
63	        }
64	
65	        @Override
66	        public void invoke(Tuple2<Long, Long> value) throws Exception {
67	            long jobId = value.f0;
68	            long timestamp = value.f1;
69	
70	            JobStageState state = jobStates.computeIfAbsent(jobId, k -> new JobStageState());
71	
72	            if (state.lastSubmitTime == -1) {
73	                // First SUBMIT event
74	                state.currentStageCount = 1;
75	                state.lastSubmitTime = timestamp;
76	                state.maxStageCount = 1;
77	            } else if (timestamp - state.lastSubmitTime <= sessionGap) {
78	                // Same stage: continue counting
79	                state.currentStageCount++;
80	                state.maxStageCount = Math.max(state.maxStageCount, state.currentStageCount);
81	                state.lastSubmitTime = timestamp;
82	            } else {
83	                // New stage: reset count
84	                state.currentStageCount = 1;
85	                state.lastSubmitTime = timestamp;
86	            }
87	        }
88	
89	        @Override
90	        public void close() throws Exception {
91	            for (Map.Entry<Long, JobStageState> entry : jobStates.entrySet()) {
92	                writer.write("(" + entry.getKey() + "," + entry.getValue().maxStageCount + ")");
93	                writer.newLine();
94	            }
95	            if (writer != null) {
96	                writer.close();
97	            }
98	        }
99	    }
100	
101	    public static class JobStageState {
102	        public int currentStageCount = 0;
103	        public int maxStageCount = 0;
104	        public long lastSubmitTime = -1;
105	    }
106	}
